// Step 2: Deterministic Pre-Classification Filter (P0-3 Approval Safety & Financial Exclusions)
const item = $input.first().json;
const subject = (item.subject || '').trim();
const body = (item.bodyPreview || item.body?.content || '').trim();
const fromAddress = item.from?.emailAddress?.address || '';

// Strict financial negative filter: Remittance Advices, Landlord Statements, Rent Statements, and Payment Confirmations
const financialPatterns = [
  /\bremittance(\s*advice)?\b/i,
  /\blandlord\s*statement\b/i,
  /\brent\s*statement\b/i,
  /\bstatement\s*of\s*account\b/i,
  /\bpayment\s*(received|confirmation|receipt|advice|processed)\b/i,
  /\bproof\s*of\s*payment\b/i,
  /\bbacs\s*(payment|transfer)\b/i,
  /\bcredit\s*note\b/i,
  /\baccount\s*statement\b/i,
  /\bmonthly\s*statement\b/i
];

const isFinancialDocument = financialPatterns.some(p => p.test(subject) || p.test(body));

// Strict chasing & complaint filter: Chasing updates, missed appointments, tenant complaints on existing works
const complaintPatterns = [
  / outstanding\s*works? /i,
  / delayed\s*appointments? /i,
  / missed\s*appointments? /i,
  / no\s*one\s*(attended|showed\s*up|turned\s*up) /i,
  / chasing\s*(an?\s*)?(update|appointment|works?|job) /i,
  / (has\s*made\s*a\s*complaint|making\s*a\s*complaint|formal\s*complaint) /i,
  / update\s*on\s*(the\s*)?(appointment|progress|attendance) /i
];

const isComplaintDocument = complaintPatterns.some(p => p.test(subject) || p.test(body));

// Explicit approval intent patterns (broad approval phrases, excludes generic 'Re: Quote')
const approvalPatterns = [
  /\b(approved|approve|proceed|go\s*ahead|accepted|accept|confirmed|proceeding)\b/i,
  /quote\s*(is\s*)?approved/i,
  /proceed\s*(with\s*(the\s*)?(quote|work|repair|job))?/i,
  /go\s*ahead\s*(with\s*(the\s*)?(quote|work|repair|job))?/i,
  /approval\s*confirmed/i,
  /please\s*(proceed|go\s*ahead|approve)/i,
  /ok\s*to\s*proceed/i,
  /customer\s*(accepts|approves)\s*quote/i,
  /partial\s*approval/i,
  /approved\s*up\s*to\s*([£$€]?\d+)/i
];

const hasDeterministicApproval = !isFinancialDocument && approvalPatterns.some(p => p.test(subject) || p.test(body));

return [{
  json: {
    messageId: item.id,
    internetMessageId: item.internetMessageId || item.id,
    subject: subject,
    bodySnippet: body.substring(0, 4000),
    fromEmail: fromAddress,
    fromName: item.from?.emailAddress?.name || '',
    hasAttachments: Boolean(item.hasAttachments),
    isDeterministicApproval: hasDeterministicApproval,
    isFinancialDocument: isFinancialDocument,
    isComplaintDocument: isComplaintDocument
  }
}];

// Quality gate failed (Low confidence, approval, missing fields, or missing fromEmail)
console.log(`[Quality Gate] Rejected: State='${$json.classification_state}', Confidence=${$json.confidence_score}. Leaving UNREAD for manual review.`);
return [];

// P1-2: Backend returned a non-success status (400/401/403/409/422/500/timeout/malformed).
// Email must remain UNREAD for manual investigation.
console.log(`[Backend Success Gate] Backend returned status ${$json.statusCode}. Email left UNREAD.`);
return [];
